const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const action = text(input.action || 'list').toLowerCase();
const clinic_name = text(input.clinic_name);
const error_event_id = Number(input.error_event_id ?? 0);
const error_fingerprint = text(input.error_fingerprint);
const status_filter = text(input.status_filter || 'open').toLowerCase();
const severity_filter = text(input.severity_filter).toLowerCase();
const actor_name = text(input.actor_name);
const resolution_note = text(input.resolution_note);
const limit = Number(input.limit ?? 50);
const confirm_action = bool(input.confirm_action);

const actions = [
  'list',
  'get',
  'acknowledge',
  'resolve',
  'ignore',
  'reopen',
];

const statuses = [
  'all',
  'open',
  'acknowledged',
  'resolved',
  'ignored',
];

const severities = [
  '',
  'warning',
  'error',
  'critical',
];

const errors = [];

if (!actions.includes(action)) {
  errors.push({
    field: 'action',
    message: 'اقدام معتبر نیست.',
  });
}

if (
  !Number.isInteger(error_event_id) ||
  error_event_id < 0
) {
  errors.push({
    field: 'error_event_id',
    message: 'شناسه خطا معتبر نیست.',
  });
}

if (
  ['get', 'acknowledge', 'resolve', 'ignore', 'reopen'].includes(action) &&
  error_event_id < 1 &&
  !error_fingerprint
) {
  errors.push({
    field: 'error_reference',
    message: 'شناسه خطا یا fingerprint الزامی است.',
  });
}

if (!statuses.includes(status_filter)) {
  errors.push({
    field: 'status_filter',
    message: 'فیلتر وضعیت معتبر نیست.',
  });
}

if (!severities.includes(severity_filter)) {
  errors.push({
    field: 'severity_filter',
    message: 'فیلتر شدت معتبر نیست.',
  });
}

if (
  !Number.isInteger(limit) ||
  limit < 1 ||
  limit > 500
) {
  errors.push({
    field: 'limit',
    message: 'Limit باید بین 1 و 500 باشد.',
  });
}

if (
  ['acknowledge', 'resolve', 'ignore', 'reopen'].includes(action) &&
  !actor_name
) {
  errors.push({
    field: 'actor_name',
    message: 'نام انجام‌دهنده الزامی است.',
  });
}

if (
  ['resolve', 'ignore'].includes(action) &&
  !resolution_note
) {
  errors.push({
    field: 'resolution_note',
    message: 'توضیح نتیجه الزامی است.',
  });
}

if (
  action !== 'list' &&
  action !== 'get' &&
  confirm_action !== true
) {
  errors.push({
    field: 'confirm_action',
    message: 'تغییر وضعیت خطا باید تأیید شود.',
  });
}

return [{
  json: {
    action,
    clinic_name,
    error_event_id,
    error_fingerprint,
    status_filter,
    severity_filter,
    actor_name,
    resolution_note,
    limit,
    confirm_action,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
